'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={dashboard:'Vue d’ensemble',campaigns:'Campagnes',prospects:'Entreprises',atlas:'ATLAS',settings:'Paramètres',diagnostics:'Diagnostics',company:'Dossier entreprise'};
const symbols=['◈','▤','◇','◎','▦','⚙','⌁'];
let session,route='dashboard',selected=new Set(),lastItems=[],total=0,offset=0,promptText='',exportId='',filters={},timer;
const fmt=v=>new Intl.NumberFormat('fr-CH').format(v),date=v=>v?new Date(v).toLocaleString('fr-CH',{timeZone:'Europe/Zurich'}):'Inconnu';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',6500);}
async function copyText(value){if(navigator.clipboard){try{await navigator.clipboard.writeText(value);return;}catch{}}const input=document.createElement('textarea');input.value=value;input.className='sr-only';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw new Error('Copie impossible dans ce navigateur. Vous pouvez sélectionner le texte.');}
async function api(path,options={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),18000);try{const response=await fetch('/api'+path,{...options,signal:controller.signal,headers:{'Content-Type':'application/json','X-Local-Token':session?.token||'',...options.headers}});if(!response.ok){let err;try{err=await response.json();}catch{err={detail:response.statusText};}throw new Error(typeof err.detail==='string'?err.detail:JSON.stringify(err.detail));}return await response.json();}catch(e){if(e.name==='AbortError')throw new Error('Le serveur local ne répond pas dans le délai prévu. Vos données sont conservées.');throw e;}finally{clearTimeout(timeout);}}
function title(eyebrow,name,description,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1><p>${description}</p></div>${action}</div>`;}
function empty(title,text,button=''){return `<div class="empty"><div class="symbol">◇</div><h3>${title}</h3><p>${text}</p>${button}</div>`;}
function options(items,value='',blank='Tous'){return `<option value="">${blank}</option>`+items.map(v=>`<option ${value===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function query(){return new URLSearchParams(Object.entries(filters).filter(([,v])=>v!==''&&v!==undefined)).toString();}

function readLocation(){
 const [path,params='']=(location.hash.slice(1)||'dashboard').split('?');route=path==='planning'?'atlas':path==='crm'?'prospects':path;
 const values=Object.fromEntries(new URLSearchParams(params));offset=Math.max(0,Number(values.offset)||0);delete values.offset;filters=values;
}
function saveLocation(){
 const params=query()+(offset?'&offset='+offset:'');history.pushState(null,'','#'+route+(params?'?'+params:''));
}
function contactActions(c){
 const disabled=(label,reason)=>`<button class="secondary" disabled title="${esc(reason)}">${label}</button>`;
 const blocked=!!c.suppressed;const outreachBlocked=blocked||c.qualification?.eligible_for_outreach===false;const outreachReason=blocked?'Entreprise à ne plus contacter':'Identité ou éligibilité à vérifier dans la fiche';
 return `<div class="actions quick-actions">
 ${c.phone?`<button class="secondary copy-value" data-action="copy-value" data-kind="phone" data-value="${esc(c.phone)}">${esc(c.phone)} ⧉</button>`:disabled('Téléphone absent','Aucun numéro disponible')}
 ${c.email?`<button class="secondary copy-value" data-action="copy-value" data-kind="email" data-value="${esc(c.email)}">${esc(c.email)} ⧉</button>`:disabled('E-mail absent','Aucun e-mail disponible')}
 ${c.website?`<a href="${esc(safeLink(c.website))}" target="_blank" rel="noopener noreferrer">Ouvrir le site ↗</a>`:disabled('Site','Site non identifié')}
 <button class="secondary" data-action="copy-contact" data-id="${c.id}">Copier les coordonnées</button>
 ${blocked?disabled('Contacté','Entreprise à ne plus contacter'):`<button class="secondary" data-action="contacted" data-id="${c.id}">Marquer contacté</button>`}
 <button class="secondary" data-action="quick-note" data-id="${c.id}">Note</button>
 </div>`;
}
function scoreLabel(score){return score?.total==null?'Non évaluée':score.total+' / 100';}


function defaultDirection(key){return ['name','phone','email','sector','city','status','website','site_status'].includes(key)?'asc':'desc';}
function sortHeader(label,key){const active=(filters.sort||'c')===key;const direction=filters.direction||defaultDirection(key);return `<th aria-sort="${active?(direction==='asc'?'ascending':'descending'):'none'}"><button class="sort-heading ${active?'active':''}" data-action="sort-column" data-key="${key}" title="Trier ${esc(label)} par ordre ${active&&direction==='asc'?'décroissant':'croissant'}">${esc(label)} <span aria-hidden="true">${active?(direction==='asc'?'↑':'↓'):'↕'}</span></button></th>`;}
function abcLabel(q,key){const v=q?.scores?.[key];if(!v||v.value==null)return 'Non évaluable';return `${Math.round(v.value)} / 100${v.status==='PROVISIONAL'?' · Provisoire':''}`;}
function scoreCell(c,key){const v=c.qualification?.scores?.[key];return `<b>${abcLabel(c.qualification,key)}</b><small>Couverture : ${Math.round(v?.coverage||0)} %</small>`;}
function qualificationSummary(c){return `<p>Grille ${esc(c.qualification?.rubric_version||'Non calculée')} · ${date(c.qualification?.computed_at)}. Les notes historiques restent conservées.</p><p>Les résultats externes dépendent des sources effectivement autorisées. Les outils non configurés restent inconnus.</p>`;}
async function auditTab(id,tab){const [c,runs]=await Promise.all([api('/companies/'+id),api(`/companies/${id}/audits`)]);const run=runs.find(r=>r.id===c.qualification?.audit_id)||runs[0];const r=run?.result||{};let html='';if(tab==='summary')html=qualificationSummary(c);else if(tab==='evidence')html=(r.evidence||[]).map(ev=>`<article class="activity"><b>${esc(ev.id)} · ${esc(ev.kind)}</b><p>${esc(ev.value_excerpt)}</p><small>${date(ev.captured_at)} · ${esc(ev.source_url)}</small></article>`).join('')||'<p>Aucune preuve collectée.</p>';else if(['objective','ai','visibility'].includes(tab)){const rows=(r.criteria||[]).filter(x=>tab==='visibility'?x.code.startsWith('B'):tab==='ai'?x.kind==='subjective':x.code.startsWith('A')&&x.kind==='objective');html=rows.map(x=>`<details><summary>${esc(x.code)} ${esc(x.label)} · ${esc(x.status)} · ${x.points_awarded==null?'Inconnu':x.points_awarded} / ${x.points_max}</summary><p>Mesure : ${esc(JSON.stringify(x.raw_value))} ${esc(x.unit||'')} · Seuils : ${esc(JSON.stringify(x.thresholds))}</p><p>Méthode : ${esc(x.method)} · ${date(x.checked_at)}</p><p>Preuves : ${x.evidence_refs.map(esc).join(', ')||'Aucune'} · ${esc(x.reason||x.error_code||'')}</p></details>`).join('')||'<p>Aucun audit. Recalculez la qualification pour afficher la grille.</p>';}else if(tab==='opportunities')html=(r.opportunities||[]).map(o=>`<article class="activity"><b>${esc(opportunityLabel(o.type))}</b><p>${esc(o.suggested_service)} · ${o.human_review_required?'Validation humaine requise':'Constat mesuré'}</p><small>Preuves : ${o.evidence_refs.map(esc).join(', ')} · ${date(o.created_at)}</small></article>`).join('')||'<p>Aucune opportunité démontrée.</p>';else if(tab==='history')html=runs.map(x=>`<details><summary>${date(x.started_at)} · ${esc(x.mode)} · ${esc(x.status)} · grille ${esc(x.rubric_version)}</summary>${['queued','running'].includes(x.status)?`<button data-action="cancel-audit" data-id="${x.id}" data-company="${c.id}">Annuler l’audit</button>`:''}<pre>${esc(JSON.stringify({scores:x.result.scores,etapes:x.stages,outils:x.tool_versions,erreur:x.error_summary},null,2))}</pre></details>`).join('')||'<p>Aucun historique.</p>';else html=`<pre>${esc(JSON.stringify(c.contacts,null,2))}</pre>`;$('#audit-tab-panel').innerHTML=html;document.querySelectorAll('.audit-tabs button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));}

async function render(){readLocation();updateSelectionBar();if(!names[route])route='dashboard';$('#nav').innerHTML=Object.entries(names).filter(([k])=>k!=='company').map(([k,v],i)=>`<a class="${route===k||(route==='company'&&k==='prospects')?'active':''}" href="#${k}"><span>${symbols[i]}</span>${v}</a>`).join('');$('#breadcrumb').textContent='Mon espace / '+names[route];$('#main').innerHTML='<p role="status">Chargement…</p>';try{if(route==='dashboard')await dashboard();else if(route==='campaigns')await campaigns();else if(route==='prospects')await prospects();else if(route==='atlas')await planningPage();else if(route==='company')await companyPage();else if(route==='settings')await settings();else await diagnostics();document.querySelectorAll('[data-width]').forEach(el=>el.style.width=el.dataset.width+'%');}catch(e){$('#main').innerHTML=title('Diagnostic','Une opération a échoué','Vos données enregistrées sont conservées.')+`<div class="notice error">${esc(e.message)}</div><button data-action="reload">Réessayer</button>`;}}

let datasetBusy=false;
function datasetCard(status){
 const job=status.job,active=job&&['queued','running'].includes(job.state);datasetBusy=!!active;
 const d=status.dataset,p=job?.progress||{};
 let meter='';
 if(active){
  if(p.total_bytes)meter=`<progress max="${Number(p.total_bytes)}" value="${Number(p.bytes)||0}"></progress><small>${fmt(Math.round((p.bytes||0)/1000000))} / ${fmt(Math.round(p.total_bytes/1000000))} Mo</small>`;
  else if(p.total_businesses)meter=`<progress max="${Number(p.total_businesses)}" value="${Number(p.classified)||0}"></progress>`;
  else meter='<progress aria-label="Préparation en cours"></progress>';
 }
 const html=`<section class="card dataset-card"><div class="section-head"><div><div class="eyebrow">Annuaire suisse sur cet ordinateur</div><h2>${status.ready?'Copie locale prête':'Préparer la recherche locale'}</h2></div><span class="badge">${active?'Préparation en cours':status.ready?'Disponible hors ligne':'Première préparation'}</span></div>
 ${status.ready?`<p>${fmt(d.businesses)} fiches OSM indexées dans toute la Suisse, pas dans cette campagne · données au ${date(d.snapshot_at)}.<br>Les recherches dans cette copie n’utilisent pas Overpass. Les contacts et sites peuvent rester incomplets.</p>`:'<p>Téléchargez une fois l’extrait suisse, puis recherchez directement sur cet ordinateur. Environ 550 Mo à télécharger ; prévoyez au moins 4 Go libres pour la préparation. Les prospects et le CRM sont conservés.</p>'}
 ${active?`<p role="status">${esc(p.message||'En attente du worker…')}</p>${meter}${p.objects_seen?`<p>${fmt(p.objects_seen)} objets pertinents lus · ${fmt(p.businesses||0)} établissements indexés</p>`:''}`:''}
 ${job?.error?`<div class="notice ${job.state==='failed'?'error':''}">${esc(job.error)}${status.ready?' La copie précédente reste utilisable.':''}</div>`:''}
 ${status.error?`<div class="notice error">${esc(status.error)} Le fichier déjà téléchargé peut être réutilisé pour reconstruire l’index.</div><button class="secondary" data-action="dataset-refresh">Télécharger une copie à jour si nécessaire</button>`:''}
 <div class="actions">${active?`<button class="secondary" data-action="dataset-cancel" data-id="${job.id}">Arrêter la préparation</button>`:`<button data-action="${status.ready?'dataset-refresh':'dataset-prepare'}">${status.ready?'Mettre à jour la copie':'Préparer la copie suisse'}</button>`}<a href="https://download.geofabrik.de/europe/switzerland.html" target="_blank" rel="noopener noreferrer">Source et licence</a></div><small>© OpenStreetMap contributors — ODbL · extrait Geofabrik. Mise à jour uniquement à votre demande.</small></section>`;
 return status.ready&&!active?`<details class="dataset-ready"><summary><span class="dot"></span> Annuaire suisse prêt · ${fmt(d.businesses)} fiches dans toute la Suisse <span class="badge quiet">Source & mise à jour</span></summary>${html}</details>`:html;
}
async function refreshDatasetPanel(){if(!$('#dataset-panel'))return;try{const status=await api('/dataset');$('#dataset-panel').innerHTML=datasetCard(status);}catch(e){toast(e.message);}}

async function dashboard(){const [d,dataset,ready]=await Promise.all([api('/dashboard'),api('/dataset'),api('/companies?screening=recommended&sort=priority&limit=8')]);$('#main').innerHTML=title('Votre espace de prospection','Votre prospection, au même endroit.','Créez une campagne, ouvrez une entreprise, puis préparez votre sélection ATLAS.','<button data-action="new-campaign">＋ Nouvelle campagne</button>')+workflow()+`<div class="metrics"><div class="metric"><span class="label">Entreprises exploitables</span><strong>${ready.total}</strong><small>Coordonnées ou site disponibles</small></div><div class="metric"><span class="label">À contacter</span><strong>${d.to_call}</strong><small>Statut enregistré</small></div><div class="metric"><span class="label">Sélection ATLAS</span><strong>${selected.size}</strong><small>Votre prochaine session</small></div><div class="metric"><span class="label">Clients</span><strong>${d.clients}</strong><small>Statut enregistré</small></div></div><section class="card"><div class="section-head"><h2>Choisir une entreprise</h2><a class="badge quiet" href="#prospects">Toutes les entreprises ↗</a></div>${ready.items.length?ready.items.map(c=>`<div class="selection-card"><div class="company-cell"><span class="table-avatar">${esc(initials(c.name))}</span><div><button class="link" data-action="detail" data-id="${c.id}">${esc(c.name)}</button><small>${esc(sectorLabel(c.sector))} · ${esc(c.city||'Localité à préciser')}</small></div></div><span class="pill status-pill" data-status="${esc(c.status)}">${esc(c.status)}</span></div>`).join(''):empty('Votre prochaine entreprise vous attend','Lancez une campagne ; les fiches sans coordonnées restent disponibles dans la vue À vérifier.','<a href="#campaigns">Ouvrir les campagnes →</a>')}</section><div id="dataset-panel" class="campaign-card">${datasetCard(dataset)}</div>`;}
const stateLabels={draft:'Brouillon',running:'En cours',paused:'En pause',failed:'Échec',stopped:'Arrêtée',completed:'Terminée',archived:'Archivée'};
async function campaigns(){const [items,dataset]=await Promise.all([api('/campaigns'),api('/dataset')]);$('#main').innerHTML=title('Découverte','Campagnes','Des recherches ciblées, des résultats traçables.','<button data-action="new-campaign">＋ Nouvelle campagne</button>')+`<div id="dataset-panel">${datasetCard(dataset)}</div><div class="notice">Source par défaut : copie suisse locale OpenStreetMap. Limite de sélection : 100 prospects par campagne. Aucun service payant activé. Overpass reste une option distante explicite.</div>`+(items.length?items.map(c=>{const p=c.progress;let actions=[];if(c.state==='draft')actions=['edit','start'];if(c.state==='running')actions=['pause','stop'];if(['paused','failed'].includes(c.state))actions=['resume','stop'];if(['completed','failed','stopped','archived'].includes(c.state))actions.push('rerun');actions.push('duplicate');return `<section class="card campaign-card"><div class="campaign-meta"><div><h2>${esc(c.name)}</h2><p>${esc(c.config.canton)} ${esc(c.config.city)} · ${c.config.sectors.map(v=>esc(sectorLabel(v))).join(', ')} · ${c.config.max_prospects} résultats maximum</p></div><span class="badge">${stateLabels[c.state]} · ${c.config.data_source==='osm-overpass'?'Overpass':'Copie locale'}</span></div><p>${esc(c.config.description)}</p>${c.website_search?.total?`<div class="notice">Recherche de sites : ${c.website_search.confirmed} associé(s), ${c.website_search.review} à vérifier, ${c.website_search.pending} en attente, ${c.website_search.blocked} bloqué(s) ou source indisponible.</div>`:''}${c.error?`<div class="notice error">${esc(c.error)} — Détails dans Diagnostics.${c.config.data_source==='osm-overpass'?' Les erreurs 502/503/504 peuvent être temporaires.':' Les données déjà enregistrées sont conservées.'}</div>`:''}${c.config.data_source==='osm-overpass'&&p.source_retry_at&&new Date(p.source_retry_at)>new Date()?`<div class="notice">Nouvelle tentative possible à partir du ${date(p.source_retry_at)}. Aucun redémarrage automatique de la campagne en échec ; utilisez Reprendre après ce délai.</div>`:''}<div class="progress-grid">${[['discovered','Découvertes'],['normalized','Normalisées'],['duplicates','Doublons'],['enriched','Enrichies'],['audited','Sites analysés'],['qualified','Qualifiées'],['errors','Erreurs d’audit'],['remaining','Restantes']].map(([k,v])=>`<div><strong>${p[k]||0}</strong>${v}</div>`).join('')}</div>${c.state==='completed'&&p.discovered===0?`<div class="notice">Aucune fiche correspondant à cette activité dans le périmètre demandé.${p.distribution?.scope_indexed_objects!=null?` ${fmt(p.distribution.scope_indexed_objects)} fiches de ce périmètre ont été examinées.`:''} ${(p.distribution?.business_resolution||[]).filter(r=>r.method==='literal_name_or_tag_value').map(r=>`« ${esc(r.term)} » n’a pas de catégorie connue : recherche du texte dans les noms et catégories uniquement.`).join(' ')} Le total de la copie suisse n’est pas le nombre de résultats de cette campagne.</div>`:''}${p.possibly_truncated?'<div class="notice">Limite de résultats atteinte : collecte non exhaustive. La commune est recherchée par son aire administrative ; la sortie par secteur reste bornée.</div>':''}<details><summary>Activités reconnues, périmètre et candidats disponibles</summary><pre>${esc(JSON.stringify(p.distribution||{},null,2))}</pre></details><div class="actions">${actions.map(a=>`<button class="secondary" data-action="campaign-${a}" data-id="${c.id}" ${a==='resume'&&c.config.data_source==='osm-overpass'&&p.source_retry_at&&new Date(p.source_retry_at)>new Date()?'disabled title="Délai de reprise Overpass en cours"':''}>${{edit:'Modifier',start:'Démarrer',pause:'Pause',resume:'Reprendre',stop:'Arrêter',archive:'Archiver',duplicate:'Dupliquer',rerun:'Relancer — 25 prospects'}[a]}</button>`).join('')}<button class="link" data-action="results" data-id="${c.id}">Voir les résultats →</button></div></section>`;}).join(''):empty('Une recherche, un objectif','Ciblez un canton et un secteur pour lancer votre première campagne.','<button data-action="new-campaign">Créer ma première campagne</button>'));}
let draftSectors=[];
function sectorLabel(value){const raw=String(value||'');const key=raw.includes('=')?raw.split('=')[1]:raw;const item=session.sector_catalog?.find(s=>s.id===key||s.label.toLocaleLowerCase('fr')===raw.toLocaleLowerCase('fr'));return item?.label||raw.replaceAll('_',' ');}
async function campaignForm(id){const c=id?(await api('/campaigns')).find(c=>c.id===id):null;const f=c?.config||{};draftSectors=[...(f.sectors||[])];modal(`<div class="eyebrow">Nouvelle collecte</div><h1>${id?'Modifier la campagne':'Créer une campagne'}</h1><form id="campaign-form" data-id="${id||''}"><label>Nom de la campagne</label><input name="name" required maxlength="200" value="${esc(f.name||'')}" placeholder="Crèches · Morges"><div class="row"><div><label>Canton</label><select name="canton">${session.cantons.map(v=>`<option ${v===(f.canton||'Vaud')?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div><label>Commune (optionnel)</label><input name="city" value="${esc(f.city||'')}" placeholder="Morges"></div></div><label>Secteurs d’activité</label><input id="sector-search" name="sector_search" autocomplete="off" placeholder="Ex. enfants, UAPE, tea-room…" aria-label="Chercher un secteur"><div id="sector-suggestions" class="sector-suggestions" aria-live="polite"></div><div id="sector-selection" class="filter-chips"></div><small>Les mots-clés aident à choisir une catégorie. Seuls les secteurs sélectionnés servent à la collecte.</small><div class="row"><div><label>Résultats maximum</label><input name="max_prospects" type="number" min="1" max="100" value="${f.max_prospects||25}" required></div><div><label>Répartition</label><select name="distribution"><option value="balanced" ${f.distribution!=='relevance'?'selected':''}>Équilibrée entre secteurs</option><option value="relevance" ${f.distribution==='relevance'?'selected':''}>Coordonnées les plus complètes</option></select></div></div><label><input name="audit_web" type="checkbox" checked> Vérifier automatiquement les sites accessibles</label><details class="compact-details"><summary>Options de collecte</summary><label>Source gratuite</label><select name="data_source"><option value="osm-local" ${f.data_source!=='osm-overpass'?'selected':''}>Copie suisse locale</option><option value="osm-overpass" ${f.data_source==='osm-overpass'?'selected':''}>Overpass distant</option></select><label>Exclusions par nom (une par ligne)</label><textarea name="exclusions">${esc((f.exclusions||[]).join('\n'))}</textarea><input name="description" type="hidden" value="${esc(f.description||'')}"></details><p class="notice">Les fiches sans coordonnées exploitables et celles sans besoin démontré sont rangées dans « À vérifier », sans être supprimées. Un audit bloqué ne donne pas une mauvaise note.</p><div class="actions"><button>Enregistrer la campagne</button></div></form>`);await sectorSuggestions('');renderSectorSelection();}
function renderSectorSelection(){if(!$('#sector-selection'))return;$('#sector-selection').innerHTML=draftSectors.map(id=>`<button type="button" class="filter-chip" data-action="remove-sector" data-sector="${esc(id)}">${esc(sectorLabel(id))} ×</button>`).join('');}
let suggestSequence=0;
async function sectorSuggestions(q){const seq=++suggestSequence;if($('#sector-suggestions'))$('#sector-suggestions').innerHTML='<p>Recherche des catégories…</p>';const items=await api('/business/suggest?q='+encodeURIComponent(q));if(seq!==suggestSequence||!$('#sector-suggestions'))return;$('#sector-suggestions').innerHTML=items.map(s=>`<button type="button" data-action="choose-sector" data-sector="${esc(s.id)}"><b>${esc(s.label)}</b><small>${s.keywords.slice(0,3).map(esc).join(' · ')}</small></button>`).join('')||'<p>Aucune catégorie correspondante. Essayez un métier ou un synonyme.</p>';}
function initials(name){return String(name||'?').split(/[\s'’]+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function persistSelection(){localStorage.setItem('atlas-selection',JSON.stringify([...selected]));updateSelectionBar();}
function qualityValue(c){const n=Number(c.quality_score?.total);return Number.isFinite(n)?Math.max(0,Math.min(100,n)):0;}
function contactHeader(){const active=filters.sort==='email';return sortHeader('Téléphone','phone').replace('</th>',`<button class="sort-heading email-sort ${active?'active':''}" data-action="sort-column" data-key="email" aria-label="Trier par e-mail">E-mail <span aria-hidden="true">${active?(filters.direction==='asc'?'↑':'↓'):'↕'}</span></button></th>`);}
function activityLabel(kind){return ({note:'Note',change:'Modification',call:'Appel',reminder:'Relance',quote:'Devis',sale:'Vente',opportunity:'Opportunité'})[kind]||kind;}
function opportunityLabel(type){return ({WEBSITE_CREATION_CANDIDATE:'Création de site à envisager',SITE_UNAVAILABLE:'Site indisponible à vérifier',MOBILE_FIX:'Adaptation mobile',PERFORMANCE_FIX:'Performance du site',TECHNICAL_SEO_FIX:'Référencement technique',CONTACT_PATH_FIX:'Parcours de contact',VISUAL_REDESIGN_REVIEW:'Refonte visuelle à étudier',LOCAL_VISIBILITY_REVIEW:'Présence locale à vérifier',BROKEN_LINKS:'Liens internes à corriger'})[type]||type;}
function knownNeed(c){return (c.facts.screening?.observed_issues||0)>0||(c.qualification?.opportunity_count||0)>0;}
function compactScore(c,key){const s=c.qualification?.scores?.[key],value=key==='opportunity'&&!knownNeed(c)?null:s?.value,checks=c.qualification?.observations_summary?.[key],partial=value==null&&key!=='opportunity'&&checks?.measured>0,display=partial?`${checks.passed}/${checks.measured}`:value==null?'—':Math.round(value),progress=partial?100*checks.passed/checks.measured:value;return `<span class="mini-score" title="${esc(abcLabel(c.qualification,key))} · couverture ${Math.round(s?.coverage||0)} %"><b>${display}</b><span class="mini-track"><svg viewBox="0 0 100 3" preserveAspectRatio="none" aria-hidden="true"><rect width="${progress==null?0:Math.max(0,Math.min(100,progress))}" height="3" fill="#7ca6ff"/></svg></span></span>${partial?'<small>Contrôles partiels</small>':s?.status==='PROVISIONAL'?'<small>Provisoire</small>':''}`;}
function scoreTile(c,key,label,color){const s=c.qualification?.scores?.[key],v=key==='opportunity'&&!knownNeed(c)?null:s?.value,checks=key==='opportunity'&&!knownNeed(c)?null:c.qualification?.observations_summary?.[key];const partial=v==null&&checks?.measured>0;const display=v!=null?Math.round(v):partial?`${checks.passed}/${checks.measured}`:'—';const progress=v!=null?v:partial?100*checks.passed/checks.measured:null;return `<section class="score-tile" aria-label="${label}"><div class="ring"><svg viewBox="0 0 72 72" role="img" aria-label="${label} : ${partial?display+' contrôles positifs, mesure partielle':v==null?'non mesuré':Math.round(v)+' sur 100'}"><circle class="track" cx="36" cy="36" r="29"/><circle class="fill ${color} ${progress==null?'unknown':''}" cx="36" cy="36" r="29" pathLength="100" stroke-dasharray="${progress==null?'3 5':Math.max(0,Math.min(100,progress))+' 100'}"/></svg><b>${display}</b></div><div><h3>${label}</h3><p>${partial?'Contrôles partiels, pas une note complète':v==null?'Non mesuré':s.status==='PROVISIONAL'?'Priorité provisoire':'Mesures disponibles'}</p><small>${checks?.measured||0} contrôles · couverture ${Math.round(s?.coverage||0)} %</small></div></section>`;}
function workflow(){return `<div class="workflow"><a href="#campaigns"><b>01</b> Créer une campagne</a><span>›</span><a href="#prospects"><b>02</b> Choisir une entreprise</a><span>›</span><a href="#atlas"><b>03</b> Préparer ATLAS</a></div>`;}
function activeChips(){const labels={q:'Recherche',campaign:'Campagne',batch:'Lot',contact:'Contacts',city:'Commune',sector:'Secteur',status:'CRM',canton:'Canton',website:'Site',min_c:'C min.',max_a:'A max.',max_b:'B max.',min_quality:'Qualité min.',eligible:'Éligibilité'};return Object.entries(filters).filter(([k,v])=>v!==''&&!['sort','direction'].includes(k)).map(([k,v])=>`<button class="filter-chip" data-action="remove-filter" data-key="${esc(k)}">${esc(labels[k]||k)} : ${esc(k==='campaign'?'sélectionnée':k==='batch'?'dernier':v)} ×</button>`).join('');}
function companyRow(c){return `<tr><td><input class="select-company" type="checkbox" data-id="${c.id}" ${selected.has(c.id)?'checked':''} aria-label="Sélectionner ${esc(c.name)}"></td><td><div class="company-cell"><span class="table-avatar" aria-hidden="true">${esc(initials(c.name))}</span><div><button class="link company-name" data-action="detail" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.city||'Ville inconnue')} · ${esc(c.canton||'Canton inconnu')}</small></div></div></td><td><div class="contact-line">${c.phone?`<button class="copy-value" data-action="copy-value" data-kind="phone" data-value="${esc(c.phone)}">${esc(c.phone)} ⧉</button>`:'<small>Téléphone absent</small>'}</div><div class="contact-line">${c.email?`<button class="copy-value" data-action="copy-value" data-kind="email" data-value="${esc(c.email)}">${esc(c.email)} ⧉</button>`:''}${c.website?`<a href="${esc(safeLink(c.website))}" target="_blank" rel="noopener noreferrer" aria-label="Ouvrir le site de ${esc(c.name)}">Ouvrir le site ↗</a>`:c.facts.website_discovery?.candidates?.some(x=>x.state==='candidate')?'<small>Site candidat à vérifier</small>':'<small>Site à rechercher</small>'}</div></td><td><small>${esc(sectorLabel(c.sector))}</small></td><td>${compactScore(c,'site')}</td><td>${compactScore(c,'visibility')}</td><td>${compactScore(c,'opportunity')}</td><td><span class="score">${qualityValue(c)}</span><small>/ 100</small></td><td><span class="pill status-pill" data-status="${esc(c.status)}">${esc(c.status)}</span></td><td><button class="secondary" data-action="detail" data-id="${c.id}" aria-label="Ouvrir le dossier de ${esc(c.name)}">↗</button></td></tr>`;}
async function prospects(){
 if(!filters.screening)filters.screening='recommended';if(!filters.sort)filters.sort='priority';
 const [data,campaigns]=await Promise.all([api('/companies?'+query()+`&offset=${offset}&limit=50`),api('/campaigns')]);lastItems=data.items;total=data.total;
 const fInput=(key,label,type='text')=>`<label>${label}<input id="filter-${key}" type="${type}" ${type==='number'?'min="0" max="100"':''} value="${esc(filters[key]??'')}"></label>`;
 const fSelect=(key,label,values)=>`<label>${label}<select id="filter-${key}">${options(values,filters[key],'Tous')}</select></label>`;
 $('#main').innerHTML=title('Qualification','Prospects','Repérez les entreprises pertinentes, vérifiez leurs contacts et ouvrez leur dossier.',`<div class="actions"><button class="secondary" data-action="import">Importer JSON</button><button class="secondary" data-action="export-json">Exporter JSON</button><button class="secondary" data-action="export-csv">CSV</button></div>`)+`<section class="filter-shell"><div class="filter-toolbar"><input id="filter-q" aria-label="Recherche" placeholder="Rechercher une entreprise ou une ville…" value="${esc(filters.q||'')}"><select id="filter-campaign" aria-label="Campagne">${options(campaigns.map(c=>c.id),filters.campaign,'Toutes les campagnes')}</select><select id="filter-screening" aria-label="Résultats à afficher">${['recommended','review','all'].map((v,i)=>`<option value="${v}" ${filters.screening===v?'selected':''}>${['Exploitables','À vérifier / sans besoin démontré','Toutes les fiches'][i]}</option>`).join('')}</select><select id="filter-contact" aria-label="Contacts">${options(['phone','no_phone','email','no_email','both','any','none'],filters.contact,'Tous les contacts')}</select><select id="filter-status" aria-label="Statut CRM">${options(session.statuses,filters.status,'Tous les statuts')}</select><button data-action="filter">Filtrer</button><button class="ghost" data-action="reset-filters" title="Effacer les filtres">Réinitialiser</button></div><details id="advanced-filters" class="filter-advanced"><summary>Affiner la recherche <span class="badge quiet">Lieu · scores · horaires</span></summary><div class="filter-groups"><div class="filter-group"><h3>Localisation & activité</h3>${fSelect('canton','Canton',session.cantons)}${fInput('city','Commune')}${fInput('sector','Secteur exact')}${fSelect('website','Site renseigné',['present','absent'])}${fSelect('site_status','Vérification du site',['NO_OFFICIAL_SITE_FOUND','OFFICIAL_SITE_CONFIRMED','SITE_CANDIDATE_UNCERTAIN','CRAWL_BLOCKED','IDENTITY_UNCERTAIN','BUSINESS_CLOSED'])}</div><div class="filter-group"><h3>Qualification & opportunité</h3>${fInput('max_a','A · Qualité du site maximum','number')}${fInput('max_b','B · Visibilité maximum','number')}${fInput('min_c','C · Opportunité minimum','number')}${fInput('min_quality','Complétude minimum','number')}${fInput('min_identity','Confiance identité minimum','number')}${fSelect('eligible','Éligible au contact',['yes','no'])}${fSelect('provisional','Évaluation provisoire',['yes','no'])}${fSelect('opportunity','Type d’opportunité',['WEBSITE_CREATION_CANDIDATE','SITE_UNAVAILABLE','MOBILE_FIX','PERFORMANCE_FIX','TECHNICAL_SEO_FIX','CONTACT_PATH_FIX','VISUAL_REDESIGN_REVIEW','LOCAL_VISIBILITY_REVIEW','BROKEN_LINKS'])}</div><div class="filter-group"><h3>Dates & disponibilité</h3>${fInput('verified_from','Vérifié à partir du','date')}${fInput('verified_to','Jusqu’au','date')}${fSelect('hours','Horaires publiés',['known','unknown','call'])}<label>Jour<select id="filter-day"><option value="">Tous</option>${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'].map((d,i)=>`<option value="${i}" ${String(filters.day)===String(i)?'selected':''}>${d}</option>`).join('')}</select></label>${fInput('at','Heure locale','time')}<details><summary>Ancien indicateur de besoin</summary>${fInput('min_score','Minimum historique','number')}${fSelect('score_state','État historique',['unknown','assessed'])}</details></div></div><div class="actions"><button data-action="filter">Appliquer les filtres avancés</button></div></details><input id="filter-batch" type="hidden" value="${esc(filters.batch||'')}"><input id="filter-sort" type="hidden" value="${esc(filters.sort||'c')}"><input id="filter-direction" type="hidden" value="${esc(filters.direction||(['name','phone','email','sector','city','status','website'].includes(filters.sort)?'asc':'desc'))}"><div class="filter-chips">${activeChips()}</div></section><div class="table-meta"><span id="result-count">${data.total} entreprise(s) · ${selected.size} sélectionnée(s) · ${data.screening_totals?.review??0} à vérifier</span><button class="link" data-action="select-filtered">Sélectionner tous les résultats filtrés (maximum 1 000)</button></div>`+
 (data.items.length?`<div class="table-wrap"><table aria-label="Entreprises à qualifier"><thead><tr><th><input id="select-page" type="checkbox" aria-label="Sélectionner cette page"></th>${sortHeader('Entreprise','name')}${contactHeader()}${sortHeader('Secteur','sector')}${sortHeader('Site','a')}${sortHeader('Présence','b')}${sortHeader('Priorité','priority')}${sortHeader('Qualité','quality')}${sortHeader('Statut CRM','status')}<th>Dossier</th></tr></thead><tbody>${data.items.map(companyRow).join('')}</tbody></table></div><div class="pagination"><button class="secondary" data-action="previous" ${offset===0?'disabled':''}>← Précédent</button><span>${offset+1}–${Math.min(offset+50,total)} / ${total}</span><button class="secondary" data-action="next" ${offset+50>=total?'disabled':''}>Suivant →</button></div>`:empty('Aucune entreprise dans cette vue','Ajustez les filtres ou lancez une campagne. Les données existantes restent conservées.'));
 const labels={phone:'Avec téléphone',no_phone:'Sans téléphone',email:'Avec e-mail',no_email:'Sans e-mail',both:'Téléphone et e-mail',any:'Au moins un contact',none:'Aucun contact',present:'Avec site',absent:'Sans site',yes:'Oui',no:'Non',known:'Horaires connus',unknown:'Inconnu',call:'Appel publié',OFFICIAL_SITE_CONFIRMED:'Site officiel confirmé',SITE_CANDIDATE_UNCERTAIN:'Site candidat à vérifier',NO_OFFICIAL_SITE_FOUND:'Site non trouvé après recherche',CRAWL_BLOCKED:'Vérification bloquée',IDENTITY_UNCERTAIN:'Identité à vérifier',BUSINESS_CLOSED:'Fermeture signalée'};
 document.querySelectorAll('.filter-shell option').forEach(o=>{if(labels[o.value])o.textContent=labels[o.value];});for(const o of $('#filter-campaign').options){const c=campaigns.find(c=>c.id===o.value);if(c)o.textContent=c.name;}updateSelectionBar();
}
async function detail(id){
 if(route!=='company'){sessionStorage.setItem('company-return',location.hash||'#prospects');history.pushState(null,'','#company?id='+encodeURIComponent(id));}
 else history.replaceState(null,'','#company?id='+encodeURIComponent(id));
 if($('#modal').open)$('#modal').close();await render();
}
function companyForms(c){const id=c.id;return {company:`<form id="company-form" data-id="${id}"><div class="row"><div><label>Nom</label><input name="name" value="${esc(c.name)}" required maxlength="300"></div><div><label>Ville</label><input name="city" value="${esc(c.city)}" maxlength="200"></div></div><div class="row"><div><label>Téléphone</label><input name="phone" value="${esc(c.phone)}" maxlength="100"></div><div><label>Site web</label><input name="website" value="${esc(c.website)}" maxlength="2000"></div></div><label>E-mail professionnel</label><input name="email" type="email" value="${esc(c.email||'')}"><label>Canton</label><input name="canton" value="${esc(c.canton||'')}"><label>Statut</label><select name="status">${session.statuses.map(s=>`<option ${s===c.status?'selected':''}>${s}</option>`).join('')}</select><label><input type="checkbox" name="do_not_contact" ${c.suppressed?'checked disabled':''}> Opposition : ne plus contacter (conservée définitivement)</label><div class="actions"><button>Enregistrer les corrections</button></div></form>`,activity:`<form id="activity-form" data-id="${id}"><input type="hidden" name="kind" value="note"><input type="hidden" name="outcome" value=""><input type="hidden" name="amount" value="0"><input type="hidden" name="due_at" value=""><label>Votre note</label><textarea name="text" maxlength="10000" placeholder="Besoin repéré, échange, prochaine action…"></textarea><div class="actions"><button>Enregistrer l’activité</button></div></form>`,hours:`<form id="hours-form" data-id="${id}"><div class="row"><div><label>Jour</label><select name="day">${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'].map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></div><div><label>Type (vérifier la source)</label><select name="type"><option value="opening">Ouverture indicative</option><option value="call">Appel explicitement publié</option></select></div></div><div class="row"><div><label>Début</label><input type="time" name="start" required></div><div><label>Fin (lendemain si avant le début)</label><input type="time" name="end" required></div></div><label>URL de la source publiée</label><input type="url" name="source" required><div class="actions"><button>Ajouter cette plage sourcée</button></div></form>`};}
function websiteResult(c,status){const job=status.job,result=job?.result||c.facts.website_discovery;const active=job&&['queued','running','paused'].includes(job.state);const stateNames={confirmed:'Site confirmé',review_required:'Site candidat à vérifier',source_unavailable:'Source de recherche indisponible',blocked:'Vérification bloquée',ambiguous:'Plusieurs domaines à vérifier',not_found:'Aucun candidat dans les sources consultées'};return `<div class="website-state"><h2>Site & coordonnées</h2>${active?(job.state==='paused'?'<span class="badge quiet">Recherche en pause</span>':'<span class="discovery-progress">Recherche en cours</span>'):`<span class="badge ${result?.state==='confirmed'?'cyan':'quiet'}">${esc(job?.state==='failed'?'Recherche interrompue':job?.state==='cancelled'?'Recherche annulée':stateNames[result?.state]||'Recherche complémentaire')}</span>`}</div><p>${c.website?`<a href="${esc(safeLink(c.website))}" target="_blank" rel="noopener noreferrer">${esc(domainLabel(c.website))} ↗</a>`:'OSM ne renseigne pas de site pour cette entreprise.'}</p><div class="actions"><button data-action="find-site" data-id="${c.id}" ${active||c.suppressed?'disabled':''}>${c.website?'Analyser le site':'Chercher dans les sources gratuites'}</button>${active?`<button class="secondary" data-action="cancel-site" data-id="${job.id}" data-company="${c.id}">Annuler</button>`:''}</div>${(result?.candidates||[]).filter(x=>x.state!=='rejected').slice(0,3).map(x=>`<div class="insight"><a href="${esc(safeLink(x.final_url||x.url))}" target="_blank" rel="noopener noreferrer">${esc(domainLabel(x.final_url||x.url))} ↗</a><p>${esc(x.reason||'En attente de vérification')}</p><small>${(x.matched_fields||[]).map(esc).join(' · ')}</small></div>`).join('')}${job?.error?`<div class="notice error">${esc(job.error)}</div>`:''}${result?.limitations?.length?`<details class="compact-details"><summary>Source et limites de la recherche</summary>${result.limitations.filter(x=>!x.startsWith('SEARCH_')).map(x=>`<p>${esc(x)}</p>`).join('')}</details>`:''}<p class="provider-indicator">Recherche gratuite à partir des sources et domaines connus. Aucun moteur payant.</p><details class="compact-details"><summary>Indiquer un site à vérifier</summary><form id="website-candidate-form" data-id="${c.id}"><label>Adresse du site candidat</label><input type="url" name="candidate" required placeholder="https://…"><div class="actions"><button>Vérifier ce site</button></div></form></details>`;}
function domainLabel(url){try{return new URL(url).hostname.replace(/^www\./,'');}catch{return url;}}
async function companyPage(){const id=filters.id;if(!id)throw new Error('Entreprise non sélectionnée');const [c,duplicates,search]=await Promise.all([api('/companies/'+encodeURIComponent(id)),api(`/companies/${encodeURIComponent(id)}/duplicates`),api(`/companies/${encodeURIComponent(id)}/website-search`)]);const q=c.qualification||{},opportunities=q.opportunities||[];const forms=companyForms(c);
 $('#main').innerHTML=`<button class="back-link" data-action="company-back">← Retour à la liste</button><section class="company-hero"><div class="company-identity"><div class="company-logo" aria-hidden="true">${esc(initials(c.name))}</div><div><div class="eyebrow">Dossier entreprise</div><h1>${esc(c.name)}</h1><p>${esc(sectorLabel(c.sector)||'Activité à préciser')} · ${esc(c.city||'Localité inconnue')} ${esc(c.canton||'')}</p><div class="badges"><span class="badge status-pill" data-status="${esc(c.status)}">${esc(c.status)}</span><span class="badge ${q.eligible_for_outreach?'cyan':'warn'}">${q.eligible_for_outreach?'Éligible selon les contrôles':'À vérifier avant contact'}</span></div></div></div><div class="actions"><button class="secondary" data-action="edit-company">Modifier la fiche</button><button data-action="select-atlas" data-id="${id}" ${c.suppressed?'disabled':''}>${selected.has(id)?'Retirer d’ATLAS':'Ajouter à ATLAS'}</button></div></section>${contactActions(c)}<div class="company-layout"><div class="company-main"><div class="score-grid">${scoreTile(c,'site','Site','')}${scoreTile(c,'visibility','Présence constatée','cyan')}${scoreTile(c,'opportunity','Priorité','violet')}</div><section class="card"><div class="section-head"><h2>Ce qui compte maintenant</h2><span class="badge quiet">${opportunities.length} opportunité(s)</span></div>${opportunities.length?opportunities.slice(0,3).map(o=>`<div class="insight"><span class="badge">${esc(o.suggested_service||o.type)}</span><p>${esc(opportunityLabel(o.type))} · ${o.human_review_required?'À valider humainement':'Constat documenté'}</p></div>`).join(''):`<p>${c.website?'Aucune opportunité démontrée pour le moment. Vérifiez le site et lancez un audit pour disposer de mesures.':'Commencez par retrouver le site et vérifier les coordonnées. L’absence d’URL dans OSM ne prouve pas l’absence de site.'}</p>`}<div class="readiness"><span>Complétude des données</span><b>${qualityValue(c)} / 100</b></div><svg viewBox="0 0 100 3" width="100%" height="5" preserveAspectRatio="none" role="img" aria-label="Complétude des données : ${qualityValue(c)} sur 100"><rect width="100" height="3" fill="#263952" rx="1"/><rect width="${qualityValue(c)}" height="3" fill="#6a9eff" rx="1"/></svg><p class="subheading">Les mesures absentes restent inconnues. Une note provisoire est toujours affichée avec sa couverture.</p><p class="provider-indicator">${esc(c.facts.screening?.reason||'Vérification commerciale à compléter.')}</p></section><section class="card campaign-card" id="website-search-panel">${websiteResult(c,search)}</section><details class="compact-details" id="company-more"><summary>Voir plus : critères, preuves et historique</summary><div class="audit-tabs" role="tablist" aria-label="Détails de qualification">${[['summary','Résumé'],['evidence','Preuves'],['objective','Audit objectif'],['ai','Audit IA'],['visibility','Visibilité'],['opportunities','Opportunités'],['history','Historique'],['contact','Contact']].map(([k,l],i)=>`<button role="tab" aria-selected="${i===0}" data-action="audit-tab" data-tab="${k}" data-id="${id}">${l}</button>`).join('')}</div><div class="actions"><button class="secondary" data-action="qualification" data-id="${id}">Actualiser les indicateurs</button><button class="secondary" data-action="identity-form" data-id="${id}">Vérifier le site officiel</button><button class="secondary" data-action="audit" data-id="${id}" ${!c.website||c.suppressed?'disabled':''}>Analyser le site</button></div><div id="audit-tab-panel" role="tabpanel">${qualificationSummary(c)}</div><div class="actions"><button class="secondary" data-action="observations-form" data-id="${id}">Importer des mesures sourcées</button><button class="secondary" data-action="audit-deep" data-id="${id}" ${!c.website||c.suppressed?'disabled':''}>Demander un audit DEEP</button><button class="secondary" data-action="enrich" data-id="${id}" ${!c.website||c.suppressed?'disabled':''}>Enrichir les coordonnées</button></div><details class="compact-details"><summary>Horaires publiés et créneaux d’appel</summary><p>${esc(c.facts.hours?.raw||'Horaires inconnus')} · Europe/Zurich</p><p>Les horaires d’ouverture ne garantissent pas une disponibilité téléphonique. Les créneaux d’appel explicitement publiés sont prioritaires.</p>${forms.hours}</details><details class="compact-details"><summary>Doublons possibles (${duplicates.length})</summary>${duplicates.map(d=>`<div class="insight"><b>${esc(d.company.name)}</b><p>${d.signals.map(esc).join(', ')}</p><button class="secondary" data-action="distinct" data-id="${id}" data-other="${d.company.id}">Déclarer distinctes</button></div>`).join('')||'<p>Aucun rapprochement téléphone/domaine détecté.</p>'}</details><details class="compact-details"><summary>Sources et ancien indicateur</summary><pre>${esc(JSON.stringify({sources:c.source_records,contacts:c.contacts,ancien_score:c.score},null,2))}</pre></details></details><details id="company-edit" class="compact-details"><summary>Corriger les informations</summary>${forms.company}</details></div><div class="company-side"><section class="card"><h2>Coordonnées</h2><div class="company-contact-list">${[['☎','Téléphone',c.phone],['@','E-mail',c.email],['↗','Site',c.website],['⌖','Adresse',c.facts.address||c.city]].map(([icon,label,value])=>`<div class="contact-item"><span class="contact-icon" aria-hidden="true">${icon}</span><div><small>${label}</small>${label==='Site'&&value?`<a href="${esc(safeLink(value))}" target="_blank" rel="noopener noreferrer">${esc(domainLabel(value))} ↗</a>`:`${['Téléphone','E-mail'].includes(label)&&value?`<button class="copy-value" data-action="copy-value" data-kind="${label==='E-mail'?'email':'phone'}" data-value="${esc(value)}">${esc(value)} ⧉</button>`:`<strong>${esc(value||'À compléter')}</strong>`}`}</div></div>`).join('')}</div><p class="provider-indicator">Source : <a href="${esc(safeLink(c.facts.source))}" target="_blank" rel="noopener noreferrer">${esc(c.facts.source?'Fiche d’origine':'Non renseignée')}</a><br>Dernière vérification : ${date(c.verified_at)}</p></section><section class="card" id="activity-card"><h2>Note de prospection</h2>${forms.activity}</section><section class="card"><div class="section-head"><h2>Activité récente</h2><span class="badge quiet">${c.activities.length}</span></div>${c.activities.slice(0,4).map(a=>`<div class="activity"><b>${esc(activityLabel(a.kind))}</b> · ${esc(a.text||a.outcome||'Activité enregistrée')}<small>${date(a.created_at)}${a.due_at?' · Relance '+date(a.due_at):''}</small></div>`).join('')||'<p>Aucune activité enregistrée.</p>'}${c.activities.length>4?`<details class="compact-details"><summary>Voir toute l’activité</summary>${c.activities.slice(4).map(a=>`<div class="activity">${esc(a.text||a.outcome||a.kind)}<small>${date(a.created_at)}</small></div>`).join('')}</details>`:''}</section></div></div>`;
}
