function safeLink(value){try{let text=String(value||'').trim().replaceAll('&amp;','&');if(!text)return '';if(!/^[a-z][a-z0-9+.-]*:/i.test(text))text='https://'+text;const u=new URL(text);return ['https:','http:'].includes(u.protocol)&&u.hostname.includes('.')&&!u.username&&!u.password?u.href:'';}catch{return '';}}
async function settings(){
 const [s,dataset,grid]=await Promise.all([api('/settings'),api('/dataset'),api('/settings/rubric')]);$('#main').innerHTML=title('Votre environnement','Paramètres','Trois scores explicables, une complétude distincte et aucune donnée inventée.')+`<div id="dataset-panel">${datasetCard(dataset)}</div><section class="card campaign-card"><h2>Sources gratuites uniquement</h2><p>Aucun service payant, clé API ou abonnement. La recherche utilise la copie suisse et les domaines déjà connus. Une URL absente de ces sources peut rester à renseigner.</p></section><section class="card"><h2>A · Site, B · Visibilité, C · Opportunité</h2><p>A et B décrivent la qualité observée. C indique l’intérêt commercial selon les signaux vérifiés et les contrôles d’éligibilité. Les données absentes restent inconnues et diminuent la couverture ; elles ne deviennent pas des défauts.</p><p>La complétude des coordonnées reste un indicateur séparé. Les anciens scores restent conservés dans les fiches et exports.</p><details><summary>Configurer les seuils et limites d’audit</summary><p>Chaque modification exige une nouvelle version de grille. Les audits déjà calculés conservent leur barème.</p><form id="rubric-form"><label>Nouvelle version de grille</label><input name="rubric_version" required value="${esc(grid.rubric_version)}"><div class="row"><div><label>Couverture minimum A/B (%)</label><input name="coverage_min" type="number" min="0" max="100" value="${grid.coverage_min}"></div><div><label>Couverture finale (%)</label><input name="coverage_final" type="number" min="0" max="100" value="${grid.coverage_final}"></div></div><label>Confiance identité minimum (%)</label><input name="identity_min" type="number" min="0" max="100" value="${grid.identity_min}"><div class="row"><div><label>Pages maximum par site (1–5)</label><input name="max_pages" type="number" min="1" max="5" value="${grid.max_pages}"></div><div><label>Profondeur maximum (0–2)</label><input name="max_depth" type="number" min="0" max="2" value="${grid.max_depth}"></div></div><label>Réutiliser un audit pendant (heures, 1–168)</label><input name="cache_ttl_hours" type="number" min="1" max="168" value="${grid.cache_ttl_hours}"><label>Nombre maximum d’essais (1–3)</label><input name="retries" type="number" min="1" max="3" value="${grid.retries}"><label>Délai réseau maximum par requête (secondes, 3–30)</label><input name="timeout_seconds" type="number" min="3" max="30" value="${grid.timeout_seconds}"><details><summary>Seuils quantitatifs du barème</summary>${Object.entries(grid.thresholds).map(([key,values])=>`<label>${esc(key)} (valeurs séparées par une virgule)</label><input name="threshold_${key}" value="${esc(values.join(', '))}">`).join('')}</details><button>Enregistrer cette nouvelle grille</button></form></details></section><div class="grid-two"><section class="card"><h2>Données et sauvegardes</h2><p>Sauvegarde cohérente dans data/backups. Restaurer application arrêtée via Restore.bat.</p><button data-action="backup">Créer une sauvegarde</button></section><section class="card"><h2>Services externes</h2><p>IA et services payants désactivés. CHF · Europe/Zurich.</p><a href="#diagnostics">Voir les diagnostics →</a></section></div>`;
}
async function diagnostics(){const d=await api('/diagnostics');$('#main').innerHTML=title('État de l’application','Diagnostics','Des états observés, sans prétendre à une connexion non vérifiée.','<button data-action="reload">Actualiser</button>')+`<div class="metrics">${['backend','database','worker'].map(k=>`<div class="metric"><span class="label">${k}</span><strong>${esc(d[k])}</strong></div>`).join('')}</div><section class="card"><div id="dataset-panel">${datasetCard(d.local_dataset)}</div><h2>Accès Overpass (optionnel)</h2><p>Test manuel d’une requête minimale, sur la même instance. Respecte le délai de la source et ne lance aucune campagne.</p><button data-action="probe-overpass">Tester l’accès à Overpass</button><pre id="overpass-probe-result">${esc(JSON.stringify(d.last_overpass_probe||{message:'Aucun test effectué dans cette installation.'},null,2))}</pre><h2>Recherche de sites</h2><pre>${esc(JSON.stringify(d.website_search,null,2))}</pre><h2>Capacités d’audit</h2><pre>${esc(JSON.stringify(d.audit_capabilities,null,2))}</pre><h2>Connecteurs</h2>${d.connectors.map(c=>`<h3>${esc(c.name||c.id)}</h3><p>${esc(c.status)} · ${esc(c.reason||c.description)}</p><p>${esc(c.rate_limit||'')}</p>`).join('')}<div class="notice">Le statut available_unverified décrit un connecteur implémenté ; seule une collecte réelle réussie démontre l’accès à la source.</div><p>Répertoire de données : ${esc(d.data_directory)}</p></section><section class="card campaign-card"><h2>Dernières erreurs</h2>${d.errors.map(e=>`<div class="notice error">${esc(e.message)}<p>${date(e.created_at)} · ${esc(e.component)} · Diagnostic ${e.id}</p></div>`).join('')||'<p>Aucune erreur enregistrée.</p>'}</section>`;}
